from pathlib import Path
import base64, html, json, mimetypes

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[2]
REFS = REPO / "art" / "isekai-quartet-references-20261009"
spec = json.loads((HERE / "motion-design.json").read_text(encoding="utf-8"))
catalog = json.loads((REFS / "catalog.json").read_text(encoding="utf-8"))
wanted = {r for state in spec["states"] for r in state["refs"]}
def data_image(path):
    mime = mimetypes.guess_type(path.name)[0] or "image/png"
    return "data:" + mime + ";base64," + base64.b64encode(path.read_bytes()).decode()
references = {r["id"]: {**r, "image": data_image(REFS / r["file"])} for r in catalog["items"] if r["id"] in wanted}
baseline = data_image(HERE / spec["baseline"])
e = html.escape
def rows(items):
    return "".join("<tr>" + "".join("<td>" + e(str(c)) + "</td>" for c in row) + "</tr>" for row in items)
def table(headings, items):
    return '<div class="table-scroll"><table><thead><tr>' + "".join("<th>" + e(h) + "</th>" for h in headings) + "</tr></thead><tbody>" + rows(items) + "</tbody></table></div>"
routing = table(["游戏触发", "动作表现", "结束／返回规则"], spec["routing"])
poses = table(["编号", "关键姿势", "覆盖动作", "需要画清楚的部分", "依据"], spec["poses"])
order = "".join('<article class="step"><span>' + e(a) + '</span><h3>' + e(b) + '</h3><p>' + e(c) + "</p></article>" for a,b,c in spec["order"])
checks = "".join("<li>" + e(s) + "</li>" for s in spec["checks"])
buttons = "".join('<button class="state-button" data-state="' + s["id"] + '" aria-pressed="' + str(i == 0).lower() + '"><span>0' + str(i+1) + ' / ' + s["api"] + '</span><b>' + s["name"] + '</b></button>' for i,s in enumerate(spec["states"]))
